SELECT genome_id,status,tax_id,phylum,genus,species FROM bted_taxonomy_records WHERE version='202610220000000000000006' AND system='ncbi' AND genome_id IN ('GCF_000005845.2','GCF_000015005.1','GCF_000196035.1','GCF_000277735.2','GCF_000742975.1','GCF_003019785.1','GCF_040166795.1','GCF_051046855.1','GCF_051122735.1') ORDER BY genome_id;
SELECT genome_id,phylum,genus FROM hf_directory_genomes WHERE version='202610220000000000000006' AND genome_id IN ('GCF_000005845.2','GCF_000015005.1','GCF_000196035.1','GCF_000277735.2','GCF_000742975.1','GCF_003019785.1','GCF_040166795.1','GCF_051046855.1','GCF_051122735.1') ORDER BY genome_id;
SELECT json_extract(summary_json,'$.counts.phylum') AS phylum_counts, json_extract(summary_json,'$.phyla') AS phyla FROM hf_directory_releases WHERE version='202610310000000000000005';
